        /// <summary>
        /// Load settings from appsettings.json
        /// </summary>
        private AppSettings LoadSettings()
        {
            try
            {
                var path = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "appsettings.json");
                if (File.Exists(path))
                {
                    var json = File.ReadAllText(path);
                    var settings = JsonConvert.DeserializeObject<AppSettings>(json) ?? new AppSettings();

                    if (NormalizeLegacyCloudConfig(settings))
                    {
                        TryPersistSettings(path, settings);
                    }

                    return settings;
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Failed to load settings: {ex.Message}");
            }
            return new AppSettings();
        }

        private static bool NormalizeLegacyCloudConfig(AppSettings settings)
        {
            // Do not overwrite Supabase URLs to mock URLs anymore.
            return false;
        }

        private static string BuildMockSupabaseUrl(string? apiBaseUrl)
        {
            if (string.IsNullOrWhiteSpace(apiBaseUrl))
            {
                return LegacyLocalMockSupabaseUrl;
            }

            var baseUrl = apiBaseUrl.TrimEnd('/');

            if (baseUrl.EndsWith("/api/v1", StringComparison.OrdinalIgnoreCase))
            {
                return baseUrl[..^"/api/v1".Length] + "/api/mock/supa";
            }

            if (baseUrl.EndsWith("/api", StringComparison.OrdinalIgnoreCase))
            {
                return baseUrl + "/mock/supa";
            }

            return baseUrl + "/api/mock/supa";
        }

        private static void TryPersistSettings(string path, AppSettings settings)
        {
            try
            {
                var updatedJson = JsonConvert.SerializeObject(settings, Formatting.Indented);
                File.WriteAllText(path, updatedJson);
            }
            catch
            {
                // Best-effort migration write.
            }
        }

        /// <summary>
        /// Save settings to appsettings.json
        /// </summary>
        public void SaveSettings(AppSettings settings)
        {
            try
            {
                var path = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "appsettings.json");
                var json = JsonConvert.SerializeObject(settings, Formatting.Indented);
                File.WriteAllText(path, json);
                
                // Reinitialize services with new settings
                InitializeServices();
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Failed to save settings: {ex.Message}");
            }
        }

        /// <summary>
        /// Initialize all services
        /// </summary>
        private void InitializeServices()
        {
            StopCompanyDetectionTimer();

            // Dispose existing services
            _tallyConnector?.Dispose();
            _apiClient?.Dispose();
            _offlineQueue?.Dispose();

            // Create new instances
            _tallyConnector = new TallyConnector(
                _settings.TallySettings.Host,
                _settings.TallySettings.Port,
                _settings.TallySettings.TimeoutSeconds
            );
            
            // Wire up Tally logs to UI
            _tallyConnector.LogReceived += (s, msg) => AddLog(msg);

            // Use Supabase URL and Key from AuthSettings
            string supabaseUrl = _settings.AuthSettings.SupabaseUrl;
            string supabaseKey = _settings.AuthSettings.SupabaseAnonKey;
            if (string.IsNullOrWhiteSpace(supabaseUrl))
            {
                supabaseUrl = BuildMockSupabaseUrl(_settings.SyncSettings.ApiBaseUrl);
            }

            if (string.IsNullOrWhiteSpace(supabaseKey))
            {
                supabaseKey = LegacyLocalMockSupabaseKey;
            }


            _apiClient = new ApiClient(
                supabaseUrl,
                supabaseKey,
                300,
                _settings.SyncSettings.TelegramBotToken
            );

            // Set User Token if logged in
            if (App.AuthService != null && App.AuthService.IsLoggedIn)
            {
                _apiClient.SetUserToken(App.AuthService.GetAccessToken() ?? "");
            }

            _offlineQueue = new OfflineQueueService(_settings.Database.Path);

            StartCompanyDetectionTimer();
        }

