        /// <summary>
        /// Start background sync timer
        /// </summary>
        public async Task<List<Company>> GetOpenCompaniesAsync()
        {
            if (_tallyConnector == null) return new List<Company>();
            return await _tallyConnector.GetOpenCompaniesAsync();
        }

        public void StartSync()
        {
            if (_syncTimer != null) return;

            _cancellationTokenSource = new CancellationTokenSource();

            // FIX: Mark first run complete when user explicitly starts auto-sync
            _isFirstRun = false;

            _syncTimer = new System.Timers.Timer(_settings.SyncSettings.SyncIntervalMinutes * 60 * 1000);
            _syncTimer.Elapsed += async (s, e) => await RunSyncAsync();
            _syncTimer.AutoReset = true;
            _syncTimer.Start();

            // Calculate next sync time
            Status.NextSyncTime = DateTime.Now.AddMinutes(_settings.SyncSettings.SyncIntervalMinutes);
            UpdateStatus(SyncState.Idle, $"Auto-sync every {_settings.SyncSettings.SyncIntervalMinutes} minutes");

            Console.WriteLine($"Background sync started (interval: {_settings.SyncSettings.SyncIntervalMinutes} min)");

            // FIX: Trigger immediate first sync when auto-sync is started
            _ = Task.Run(async () => 
            {
                await Task.Delay(2000); // Small delay to let UI update
                await RunSyncAsync(isManual: false, forceResync: false);
            });
        }

        /// <summary>
        /// Stop background sync
        /// </summary>
        public void StopSync()
        {
            _syncTimer?.Stop();
            _syncTimer?.Dispose();
            _syncTimer = null;

            _cancellationTokenSource?.Cancel();

            UpdateStatus(SyncState.Idle, "Sync stopped");
            Console.WriteLine("Background sync stopped");
        }

        private void StartCompanyDetectionTimer()
        {
            if (_companyDetectionTimer != null) return;

            _companyDetectionTimer = new System.Timers.Timer(5000); // Check every 5 seconds
            _companyDetectionTimer.Elapsed += async (s, e) => await DetectCompanyAndNotifyAsync();
            _companyDetectionTimer.AutoReset = true;
            _companyDetectionTimer.Start();

            // Run once immediately on startup
            _ = Task.Run(async () => await DetectCompanyAndNotifyAsync());
        }

        private void StopCompanyDetectionTimer()
        {
            _companyDetectionTimer?.Stop();
            _companyDetectionTimer?.Dispose();
            _companyDetectionTimer = null;
        }

        private async Task DetectCompanyAndNotifyAsync()
        {
            // If background sync is active, do not poll to avoid collision
            if (_isSyncing) return;

            lock (_detectionLock)
            {
                if (_isDetecting) return;
                _isDetecting = true;
            }

            try
            {
                if (_tallyConnector == null) return;

                // Test connection to Tally
                var tallyResult = await _tallyConnector.TestConnectionAsync();
                bool isTallyConnected = tallyResult.Success;
                
                string? companyName = null;
                Company? activeCompany = null;

                if (isTallyConnected)
                {
                    try
                    {
                        activeCompany = await _tallyConnector.GetActiveCompanyAsync();
                        if (activeCompany != null)
                        {
                            companyName = activeCompany.Name;
                        }
                    }
                    catch
                    {
                        // Ignore connection/parse errors
                    }
                }

                // Update Status properties only if changed, and notify UI
                bool changed = false;

                if (Status.IsTallyConnected != isTallyConnected)
                {
                    Status.IsTallyConnected = isTallyConnected;
                    changed = true;
                }

                if (Status.CompanyName != companyName)
                {
                    Status.CompanyName = companyName;
                    CurrentCompany = activeCompany;
                    changed = true;
                }

                if (changed)
                {
                    StatusChanged?.Invoke(this, Status);
                }
            }
            catch
            {
                // Never let background timer crash the app
            }
            finally
            {
                lock (_detectionLock)
                {
                    _isDetecting = false;
                }
            }
        }

        /// <summary>
        /// Manual sync trigger
        /// </summary>
        public async Task RunManualSyncAsync(bool forceResync = false)
        {
            await RunSyncAsync(isManual: true, forceResync: forceResync);
        }

