        /// <summary>
        /// Update status and notify listeners
        /// </summary>
        private void UpdateStatus(SyncState state, string message, string? entityName = null)
        {
            Status.State = state;
            Status.Message = message;
            Status.CurrentOperation = entityName;
            Status.Error = state == SyncState.Error ? entityName : null;

            StatusChanged?.Invoke(this, Status);
        }

        private void AddLog(string message)
        {
            SyncLogRequested?.Invoke(this, TextSanitizer.Normalize(message));
        }

        private void PublishItemSyncStatus(string name, string type, string status, string? error = null)
        {
            ItemSynced?.Invoke(this, new SyncItemStatus
            {
                Name = string.IsNullOrWhiteSpace(name) ? "Unnamed" : name,
                Type = string.IsNullOrWhiteSpace(type) ? "Unknown" : type,
                Status = status,
                Error = error,
                Timestamp = DateTime.Now
            });
        }

        private static void EnsureVoucherIds(List<Voucher> vouchers, string companyId)
        {
            foreach (var voucher in vouchers)
            {
                if (voucher == null)
                {
                    continue;
                }

                if (string.IsNullOrWhiteSpace(voucher.VoucherId))
                {
                    voucher.GenerateDeterministicId(companyId);
                }
                else if (!Guid.TryParse(voucher.VoucherId, out _))
                {
                    voucher.VoucherId = ApiClient.GenerateDeterministicGuid(voucher.VoucherId).ToString();
                }
            }
        }

        private async Task MirrorSuccessfulPendingVoucherAsync(
            Company company,
            JToken? voucherToken,
            string normalizedType,
            string? voucherNumber,
            DateTime voucherDate,
            string partyLedger,
            decimal amount,
            string? narration,
            List<VoucherLedgerEntry> ledgerEntries,
            List<VoucherInventoryEntry> inventoryEntries)
        {
            if (_apiClient == null)
            {
                return;
            }

            try
            {
                var effectiveVoucherNumber = string.IsNullOrWhiteSpace(voucherNumber)
                    ? GetTokenString(voucherToken, "voucher_number", "voucherNumber", "invoice_number", "invoiceNumber") ?? "0"
                    : voucherNumber.Trim();

                var normalizedLedgerEntries = (ledgerEntries ?? new List<VoucherLedgerEntry>())
                    .Where(entry => entry != null && !string.IsNullOrWhiteSpace(entry.LedgerName) && entry.Amount != 0m)
                    .Select(entry => new VoucherLedgerEntry
                    {
                        LedgerName = entry.LedgerName,
                        Amount = entry.Amount,
                        IsDebit = entry.IsDebit
                    })
                    .ToList();

                var normalizedInventoryEntries = (inventoryEntries ?? new List<VoucherInventoryEntry>())
                    .Where(entry => entry != null && !string.IsNullOrWhiteSpace(entry.StockItemName) && entry.Amount > 0m)
                    .Select(entry => new VoucherInventoryEntry
                    {
                        StockItemName = entry.StockItemName,
                        Quantity = entry.Quantity,
                        Unit = entry.Unit,
                        Rate = entry.Rate,
                        Amount = entry.Amount,
                        DiscountPercent = entry.DiscountPercent,
                        HsnCode = entry.HsnCode,
                        TaxRate = entry.TaxRate,
                        Taxability = entry.Taxability
                    })
                    .ToList();

                JObject rawData = voucherToken is JObject rawObject
                    ? (JObject)rawObject.DeepClone()
                    : new JObject();

                foreach (var key in new[] { "items", "inventory_entries", "inventoryEntries", "stock_entries", "stockEntries", "ledger_entries", "ledgerEntries" })
                {
                    rawData.Remove(key);
                }

                if (normalizedInventoryEntries.Count > 0)
                {
                    var inventoryToken = JArray.FromObject(normalizedInventoryEntries);
                    rawData["items"] = inventoryToken.DeepClone();
                    rawData["inventory_entries"] = inventoryToken;
                }

                if (normalizedLedgerEntries.Count > 0)
                {
                    rawData["ledger_entries"] = JArray.FromObject(normalizedLedgerEntries);
                }

                rawData["voucher_type"] = normalizedType;
                rawData["voucher_type_name"] = normalizedType;
                rawData["voucher_number"] = effectiveVoucherNumber;
                rawData["invoice_number"] = effectiveVoucherNumber;
                rawData["voucher_date"] = voucherDate.ToString("yyyy-MM-dd");
                rawData["invoice_date"] = voucherDate.ToString("yyyy-MM-dd");
                rawData["party_name"] = partyLedger;
                rawData["total_amount"] = Math.Abs(amount);
                rawData["grand_total"] = Math.Abs(amount);
                rawData["narration"] = narration ?? string.Empty;
                rawData["is_invoice"] = normalizedInventoryEntries.Count > 0;
                rawData["is_accounting_voucher"] = normalizedInventoryEntries.Count == 0;
                rawData["push_mode"] = normalizedInventoryEntries.Count > 0 ? "inventory" : "accounting";

                var voucher = new Voucher
                {
                    CompanyId = company.Id,
                    VoucherType = normalizedType,
                    VoucherNumber = effectiveVoucherNumber,
                    VoucherDate = voucherDate.Date,
                    PartyName = partyLedger,
                    PartyGstin = GetTokenString(voucherToken, "party_gstin", "gstin", "customer_gstin", "partyGstin"),
                    PartyAddress = GetTokenString(voucherToken, "party_address", "address", "customer_address", "partyAddress"),
                    PartyState = GetTokenString(voucherToken, "party_state", "state", "partyState"),
                    PlaceOfSupply = GetTokenString(voucherToken, "place_of_supply", "placeOfSupply"),
                    Narration = narration,
                    TotalAmount = Math.Abs(amount),
                    LedgerEntries = normalizedLedgerEntries,
                    InventoryEntries = normalizedInventoryEntries,
                    IsInvoice = normalizedInventoryEntries.Count > 0,
                    IsAccountingVoucher = normalizedInventoryEntries.Count == 0,
                    RawData = rawData
                };

                voucher.GenerateDeterministicId(company.Id);
                var vouchers = new List<Voucher> { voucher };
                EnsureVoucherIds(vouchers, company.Id);

                var ownerId = App.AuthService?.CurrentSession?.UserId;
                var voucherMirrorResult = await _apiClient.SyncDataAsync(company.Id, "vouchers", vouchers, "id", ownerId);
                if (!voucherMirrorResult.Success)
                {
                    AddLog($"   [WARN] Local voucher mirror upload failed for voucher {effectiveVoucherNumber}: {voucherMirrorResult.Error}");
                    return;
                }

                var (ledgerEntryCount, stockEntryCount) = await _apiClient.SyncVoucherEntriesAsync(company.Id, vouchers, ownerId);
                AddLog($"   [MIRROR] Local voucher mirror saved ({ledgerEntryCount} ledger, {stockEntryCount} stock entries) for voucher {effectiveVoucherNumber}.");
            }
            catch (Exception ex)
            {
                AddLog($"   [WARN] Local voucher mirror failed: {ex.Message}");
            }
        }

        private static string DeterministicGuidOrFallback(params string?[] seeds)
        {
            var normalized = seeds
                .Where(s => !string.IsNullOrWhiteSpace(s))
                .Select(s => s!.Trim())
                .Distinct(StringComparer.Ordinal)
                .ToList();

            if (normalized.Count == 1 && Guid.TryParse(normalized[0], out var existingGuid))
            {
                return existingGuid.ToString();
            }

            var seed = normalized.Count > 0
                ? string.Join("|", normalized)
                : Guid.NewGuid().ToString("N");

            return ApiClient.GenerateDeterministicGuid(seed).ToString();
        }

        /// <summary>
        /// Split list into batches
        /// </summary>
        private static List<List<T>> ChunkList<T>(List<T> list, int chunkSize)
        {
            var chunks = new List<List<T>>();
            for (int i = 0; i < list.Count; i += chunkSize)
            {
                chunks.Add(list.GetRange(i, Math.Min(chunkSize, list.Count - i)));
            }
            return chunks;
        }

        /// <summary>
        /// Helper to get display name from any Tally model
        /// </summary>
        private string GetItemDisplayName(object item)
        {
            if (item == null) return "Unknown";
            
            // Try to find Name, VoucherNumber, or InvoiceNumber property
            var type = item.GetType();
            var nameProp = type.GetProperty("Name") ?? 
                           type.GetProperty("VoucherNumber") ?? 
                           type.GetProperty("InvoiceNumber");
            
            if (nameProp != null)
            {
                return nameProp.GetValue(item)?.ToString() ?? "Unnamed";
            }

            return item.ToString() ?? "Unnamed";
        }

        // ============================================
        // TWO-WAY SYNC: Push Cloud entries TO Tally
        // ============================================

        /// <summary>
        /// Process pending transactions from Cloud and push them to Tally
        /// Called when Tally is open and sync runs
        /// </summary>
        private async Task ProcessPendingTransactionsAsync(Company company)
        {
            try
            {
                if (_apiClient == null || _tallyConnector == null) return;

                var pending = await _apiClient.GetPendingTransactionsAsync(company.Id);
                if (pending.Count == 0)
                {
                    return;
                }

                AddLog($"Found {pending.Count} pending entries to push to Tally");
                UpdateStatus(SyncState.Syncing, $"Pushing {pending.Count} entries to Tally...");

                string? preferredSalesLedger = null;
                string? preferredPurchaseLedger = null;
                HashSet<string>? knownLedgerNames = null;
                HashSet<string>? knownVoucherTypeNames = null;
                HashSet<string>? knownUnitNames = null;
                try
                {
                    var knownLedgers = await _tallyConnector.GetLedgersAsync(company.Name);
                    knownLedgerNames = knownLedgers
                        .Where(ledger => ledger != null && !string.IsNullOrWhiteSpace(ledger.Name))
                        .Select(ledger => ledger.Name.Trim())
                        .ToHashSet(StringComparer.OrdinalIgnoreCase);

                    preferredSalesLedger = ResolvePreferredBusinessLedgerFromGroups(knownLedgers, isSalesLike: true);
                    preferredPurchaseLedger = ResolvePreferredBusinessLedgerFromGroups(knownLedgers, isSalesLike: false);

                    if (string.IsNullOrWhiteSpace(preferredSalesLedger))
                    {
                        preferredSalesLedger = ResolveFallbackBusinessLedgerName(knownLedgerNames, isSalesLike: true, isPurchaseLike: false, partyLedger: null);
                    }

                    if (string.IsNullOrWhiteSpace(preferredPurchaseLedger))
                    {
                        preferredPurchaseLedger = ResolveFallbackBusinessLedgerName(knownLedgerNames, isSalesLike: false, isPurchaseLike: true, partyLedger: null);
                    }
                }
                catch (Exception ledgerLoadEx)
                {
                    AddLog($"   Could not preload ledger list for business ledger mapping: {ledgerLoadEx.Message}");
                }

                try
                {
                    var knownVoucherTypes = await _tallyConnector.GetVoucherTypesAsync(company.Name);
                    knownVoucherTypeNames = knownVoucherTypes
                        .Where(item => item != null && !string.IsNullOrWhiteSpace(item.Name))
                        .Select(item => item.Name.Trim())
                        .ToHashSet(StringComparer.OrdinalIgnoreCase);
                }
                catch (Exception voucherTypeLoadEx)
                {
                    AddLog($"   Could not preload voucher types for pending push: {voucherTypeLoadEx.Message}");
                }

                try
                {
                    var knownUnits = await _tallyConnector.GetUnitsAsync(company.Name);
                    knownUnitNames = knownUnits
                        .Where(item => item != null && !string.IsNullOrWhiteSpace(item.Name))
                        .Select(item => item.Name.Trim())
                        .ToHashSet(StringComparer.OrdinalIgnoreCase);
                }
                catch (Exception unitLoadEx)
                {
                    AddLog($"   Could not preload units for pending push: {unitLoadEx.Message}");
                }

                bool pendingStockMetaReady = _stockItemMetaCache.Count > 0
                    && string.Equals(_stockMetaCompanyId, company.Id, StringComparison.OrdinalIgnoreCase);
                if (!pendingStockMetaReady)
                {
                    try
                    {
                        _hsnCache.Clear();
                        _stockItemMetaCache.Clear();
                        var stockItems = await _tallyConnector.GetStockItemsAsync(company.Name);
                        UpsertStockItemMetaCache(stockItems);
                        _stockMetaCompanyId = company.Id;
                        _hsnCache = _stockItemMetaCache.Values
                            .Where(meta => !string.IsNullOrWhiteSpace(meta.HsnCode))
                            .GroupBy(meta => meta.Name, StringComparer.OrdinalIgnoreCase)
                            .ToDictionary(g => g.Key, g => g.First().HsnCode.Trim(), StringComparer.OrdinalIgnoreCase);
                        AddLog($"   Loaded stock metadata for pending push: {_stockItemMetaCache.Count} items | Company={company.Name}");
                    }
                    catch (Exception stockMetaEx)
                    {
                        AddLog($"   Could not preload stock metadata for pending push: {stockMetaEx.Message}");
                    }
                }
                int successCount = 0;
                int failCount = 0;

                foreach (var transaction in pending)
                {
                    var currentAttempt = GetRetryAttempt(transaction);
                    var attemptNumber = currentAttempt + 1;
                    AddLog($"   [RETRY] Processing pending transaction {transaction.Id} ({transaction.TransactionType}) attempt {attemptNumber}/{MaxPendingPushRetries}");

                    try
                    {
                        await _apiClient.UpdatePendingTransactionStatusAsync(
                            transaction.Id,
                            "processing",
                            null,
                            null,
                            currentAttempt);

                        JToken? voucherToken = ToJToken((object?)transaction.VoucherData);
                        if (voucherToken == null)
                        {
                            var nextAttempt = currentAttempt + 1;
                            var nextStatus = nextAttempt < MaxPendingPushRetries ? "pending" : "failed";
                            var retryError = AppendRetryMetadata("No voucher data provided", nextAttempt);

                            await _apiClient.UpdatePendingTransactionStatusAsync(
                                transaction.Id,
                                nextStatus,
                                null,
                                retryError,
                                nextAttempt);

                            AddLog($"   Failed attempt {nextAttempt}/{MaxPendingPushRetries}: No voucher data provided");
                            PublishItemSyncStatus(transaction.TransactionType, transaction.Id, "Error", "No voucher data provided");
                            failCount++;
                            continue;
                        }

                        string partyLedger = GetTokenString(
                            voucherToken,
                            "party_ledger_name",
                            "partyLedgerName",
                            "party_name",
                            "partyName",
                            "customer_name",
                            "customerName") ?? string.Empty;

                        decimal amount = GetTokenDecimal(
                            voucherToken,
                            "net_amount",
                            "amount",
                            "total_amount",
                            "grand_total",
                            "total",
                            "totalAmount") ?? 0m;

                        var parsedVoucherDate = GetTokenDate(
                            voucherToken,
                            "invoice_date",
                            "invoiceDate",
                            "voucher_date",
                            "voucherDate",
                            "date",
                            "entry_date",
                            "entryDate");

                        DateTime voucherDate;
                        if (parsedVoucherDate.HasValue && IsValidVoucherDate(parsedVoucherDate.Value))
                        {
                            voucherDate = parsedVoucherDate.Value.Date;
                        }
                        else if (IsValidVoucherDate(transaction.CreatedAt))
                        {
                            voucherDate = transaction.CreatedAt.Date;
                            AddLog($"   Voucher date missing/invalid, using created date {voucherDate:dd-MMM-yyyy}");
                        }
                        else
                        {
                            voucherDate = DateTime.Today;
                            AddLog($"   Voucher date missing/invalid, using today {voucherDate:dd-MMM-yyyy}");
                        }

                        string narration = GetTokenString(voucherToken, "narration", "notes", "description", "memo")
                            ?? "Created from TallySync App";

                        string normalizedType = NormalizeTallyVoucherType(transaction.TransactionType, transaction.VoucherData);
                        bool isSalesLikeType = normalizedType.Contains("sale", StringComparison.OrdinalIgnoreCase);
                        bool isPurchaseLikeType = normalizedType.Contains("purchase", StringComparison.OrdinalIgnoreCase);
                        string? preferredBusinessLedger = isSalesLikeType
                            ? preferredSalesLedger
                            : isPurchaseLikeType
                                ? preferredPurchaseLedger
                                : null;

                        var inventoryEntries = ExtractInventoryEntries(voucherToken);
                        var ledgerEntries = ExtractLedgerEntries(voucherToken);

                        if (inventoryEntries.Count == 0 && (isSalesLikeType || isPurchaseLikeType))
                        {
                            var itemKeyHints = GetPresentTokenKeys(
                                voucherToken,
                                "items",
                                "stock_entries",
                                "inventory_entries",
                                "stockEntries",
                                "inventoryEntries",
                                "sales_items",
                                "purchase_items",
                                "line_items",
                                "lineItems");
                            if (itemKeyHints.Count > 0)
                            {
                                AddLog($"   [WARN] Item-like payload keys present but no inventory rows were extracted: {string.Join(", ", itemKeyHints)}");
                            }
                        }

                        var (filledTaxRateCount, filledHsnCount, filledUnitCount) = ApplyStockItemMetaFallbacks(inventoryEntries);
                        if (filledTaxRateCount > 0 || filledHsnCount > 0 || filledUnitCount > 0)
                        {
                            AddLog($"   Enriched item metadata from stock masters: taxRates={filledTaxRateCount}, hsn={filledHsnCount}, units={filledUnitCount}");
                        }

                        bool allowAccountingFallback = GetAccountingFallbackPreference(voucherToken)
                            ?? _settings.SyncSettings.AllowAccountingFallbackForInventoryFailure;
                        decimal cgstAmount = Math.Abs(GetTokenDecimal(voucherToken, "cgst_amount", "cgst", "total_cgst") ?? 0m);
                        decimal sgstAmount = Math.Abs(GetTokenDecimal(voucherToken, "sgst_amount", "sgst", "total_sgst") ?? 0m);
                        decimal igstAmount = Math.Abs(GetTokenDecimal(voucherToken, "igst_amount", "igst", "total_igst") ?? 0m);
                        decimal cessAmount = Math.Abs(GetTokenDecimal(voucherToken, "cess_amount", "cess") ?? 0m);
                        decimal inferredTaxTotal = cgstAmount + sgstAmount + igstAmount + cessAmount;
                        decimal roundOffAmount = Math.Round(GetTokenDecimal(voucherToken, "round_off", "roundOff") ?? 0m, 2, MidpointRounding.AwayFromZero);
                        if (Math.Abs(roundOffAmount) >= 0.01m)
                        {
                            string configuredRoundOffLedger = GetTokenString(voucherToken, "round_off_ledger", "round_off_ledger_name", "roundoff_ledger", "roundoff_ledger_name")
                                ?? "Round Off";
                            string resolvedRoundOffLedger = configuredRoundOffLedger;

                            if (knownLedgerNames != null)
                            {
                                resolvedRoundOffLedger = knownLedgerNames
                                    .FirstOrDefault(name => string.Equals(name, configuredRoundOffLedger, StringComparison.OrdinalIgnoreCase))
                                    ?? knownLedgerNames.FirstOrDefault(name => name.Contains("round", StringComparison.OrdinalIgnoreCase))
                                    ?? configuredRoundOffLedger;
                            }

                            bool hasRoundOffLedger = ledgerEntries.Any(entry =>
                                entry != null
                                && !string.IsNullOrWhiteSpace(entry.LedgerName)
                                && (string.Equals(entry.LedgerName.Trim(), resolvedRoundOffLedger, StringComparison.OrdinalIgnoreCase)
                                    || entry.LedgerName.Contains("round", StringComparison.OrdinalIgnoreCase)));

                            if (!hasRoundOffLedger)
                            {
                                decimal signedRoundOffAmount = isPurchaseLikeType ? -roundOffAmount : roundOffAmount;
                                ledgerEntries.Add(new VoucherLedgerEntry
                                {
                                    LedgerName = resolvedRoundOffLedger,
                                    Amount = signedRoundOffAmount,
                                    IsDebit = signedRoundOffAmount < 0
                                });
                                AddLog($"   Added round-off ledger '{resolvedRoundOffLedger}' amount={signedRoundOffAmount:0.##}");
                            }
                        }

                        // Fallback: derive GST from line items if voucher-level GST totals are missing.
                        if (inferredTaxTotal <= 0m && inventoryEntries.Count > 0)
                        {
                            decimal derivedTaxTotal = inventoryEntries
                                .Where(entry => entry != null && entry.TaxRate.HasValue && entry.TaxRate.Value > 0 && entry.Amount > 0)
                                .Sum(entry => Math.Abs(entry.Amount) * (entry.TaxRate!.Value / 100m));

                            if (derivedTaxTotal > 0m)
                            {
                                bool preferIgst = GetTokenBool(voucherToken, "is_inter_state", "is_interstate", "isInterState", "inter_state", "interState", "use_igst", "useIgst") == true;
                                if (preferIgst)
                                {
                                    igstAmount = Math.Round(derivedTaxTotal, 2, MidpointRounding.AwayFromZero);
                                    cgstAmount = 0m;
                                    sgstAmount = 0m;
                                }
                                else
                                {
                                    cgstAmount = Math.Round(derivedTaxTotal / 2m, 2, MidpointRounding.AwayFromZero);
                                    sgstAmount = Math.Round(derivedTaxTotal - cgstAmount, 2, MidpointRounding.AwayFromZero);
                                    igstAmount = 0m;
                                }

                                inferredTaxTotal = cgstAmount + sgstAmount + igstAmount + cessAmount;
                                AddLog($"   Derived GST from item tax rates: CGST={cgstAmount:0.##}, SGST={sgstAmount:0.##}, IGST={igstAmount:0.##}");
                            }
                        }

                        if (amount <= 0 && inventoryEntries.Count > 0)
                        {
                            amount = inventoryEntries.Sum(entry => Math.Abs(entry.Amount)) + inferredTaxTotal + roundOffAmount;
                        }

                        if (amount <= 0 && ledgerEntries.Count > 0)
                        {
                            amount = ledgerEntries.Sum(entry => Math.Abs(entry.Amount));
                        }

                        if (string.IsNullOrWhiteSpace(partyLedger))
                        {
                            partyLedger = ledgerEntries
                                .Select(entry => entry.LedgerName)
                                .FirstOrDefault(name => !string.IsNullOrWhiteSpace(name))
                                ?? "Cash";
                        }

                        if (inventoryEntries.Count > 0)
                        {
                            var fallbackLedgerEntries = BuildInventoryVoucherLedgerFallbacks(
                                voucherToken,
                                normalizedType,
                                partyLedger,
                                amount,
                                cgstAmount,
                                sgstAmount,
                                igstAmount,
                                cessAmount,
                                ledgerEntries,
                                knownLedgerNames);

                            if (fallbackLedgerEntries.Count > 0)
                            {
                                ledgerEntries.AddRange(fallbackLedgerEntries);
                                AddLog($"   Added {fallbackLedgerEntries.Count} fallback ledger entries for inventory/tax balancing.");
                            }
                        }

                        if (string.IsNullOrWhiteSpace(preferredBusinessLedger))
                        {
                            preferredBusinessLedger = ResolveFallbackBusinessLedgerName(
                                knownLedgerNames,
                                isSalesLikeType,
                                isPurchaseLikeType,
                                partyLedger);
                        }

                        var validationResult = InspectPendingVoucherMasters(
                            normalizedType,
                            partyLedger,
                            preferredBusinessLedger,
                            ledgerEntries,
                            inventoryEntries,
                            knownLedgerNames,
                            knownVoucherTypeNames,
                            knownUnitNames);

                        LogPendingVoucherValidation(
                            normalizedType,
                            partyLedger,
                            voucherDate,
                            amount,
                            inventoryEntries,
                            ledgerEntries,
                            company,
                            validationResult);

                        var pushContext = BuildPendingPushContext(
                            transaction.Id,
                            normalizedType,
                            partyLedger,
                            voucherDate,
                            amount,
                            inventoryEntries,
                            ledgerEntries,
                            cgstAmount,
                            sgstAmount,
                            igstAmount,
                            cessAmount);

                        AddLog($"   [PUSH] Mode={(inventoryEntries.Count > 0 ? "inventory" : "accounting")}, AllowAccountingFallback={allowAccountingFallback}");
                        AddLog($"   [PUSH] {pushContext}");

                        var (success, voucherNumber, error) = await _tallyConnector.PushVoucherToTallyAsync(
                            company.Name,
                            normalizedType,
                            voucherDate,
                            partyLedger,
                            amount,
                            narration,
                            ledgerEntries.Count > 0 ? ledgerEntries : null,
                            inventoryEntries.Count > 0 ? inventoryEntries : null,
                            preferredBusinessLedger,
                            knownLedgerNames,
                            company.FinancialYearStart,
                            company.FinancialYearEnd,
                            company.BooksStartDate
                        );

                        if (success)
                        {
                            await _apiClient.UpdatePendingTransactionStatusAsync(transaction.Id, "synced", voucherNumber, null, 0);
                            await MirrorSuccessfulPendingVoucherAsync(
                                company,
                                voucherToken,
                                normalizedType,
                                voucherNumber,
                                voucherDate,
                                partyLedger,
                                amount,
                                narration,
                                ledgerEntries,
                                inventoryEntries);
                            AddLog($"   Created in Tally: {voucherNumber}");
                            PublishItemSyncStatus(partyLedger, normalizedType, "Success");
                            successCount++;
                        }
                        else
                        {
                            if (IsVoucherDateMissingError(error))
                            {
                                AddLog($"   Tally reported a voucher date/period validation error for {voucherDate:dd-MMM-yyyy}. The app will not rewrite the voucher date automatically.");
                                AddLog("   Verify Tally current period/books period and retry with the original business date.");

                                var educationalModeHint = GetEducationalModeDateRestrictionHint(voucherDate);
                                if (!string.IsNullOrWhiteSpace(educationalModeHint))
                                {
                                    AddLog($"   {educationalModeHint}");
                                }

                                error = string.IsNullOrWhiteSpace(error)
                                    ? "Tally rejected the voucher date/period. Automatic date rewrite is disabled; verify Tally current period/books period and retry with the original voucher date."
                                    : error + " Automatic date rewrite is disabled; verify Tally current period/books period and retry with the original voucher date.";

                                if (!string.IsNullOrWhiteSpace(educationalModeHint) && !error.Contains(educationalModeHint, StringComparison.OrdinalIgnoreCase))
                                {
                                    error += " " + educationalModeHint;
                                }
                            }

                            if (TryExtractMissingStockItemName(error, out var missingStockItemName))
                            {
                                var missingItem = inventoryEntries.FirstOrDefault(item =>
                                    item != null
                                    && !string.IsNullOrWhiteSpace(item.StockItemName)
                                    && string.Equals(item.StockItemName.Trim(), missingStockItemName, StringComparison.OrdinalIgnoreCase))
                                    ?? new VoucherInventoryEntry
                                    {
                                        StockItemName = missingStockItemName,
                                        Quantity = 1,
                                        Unit = "Nos",
                                        Amount = 1,
                                        Rate = 1
                                    };

                                AddLog($"   [RETRY] Missing stock item '{missingStockItemName}' detected. Attempting auto-create in Tally...");
                                var (stockCreateSuccess, stockCreateError) = await _tallyConnector.CreateStockItemAsync(company.Name, missingItem);

                                if (stockCreateSuccess)
                                {
                                    if (!_hsnCache.ContainsKey(missingStockItemName))
                                    {
                                        _hsnCache[missingStockItemName] = missingItem.HsnCode?.Trim() ?? string.Empty;
                                    }
                                    _stockItemMetaCache[missingStockItemName] = new StockItemPushMeta
                                    {
                                        Name = missingStockItemName,
                                        GstRate = Math.Abs(missingItem.TaxRate ?? 0m),
                                        HsnCode = missingItem.HsnCode?.Trim() ?? string.Empty,
                                        Unit = missingItem.Unit?.Trim() ?? string.Empty
                                    };

                                    AddLog($"   [RETRY] Stock item '{missingStockItemName}' created. Retrying voucher push...");
                                    var (stockRetrySuccess, stockRetryVoucherNumber, stockRetryErrorMessage) = await _tallyConnector.PushVoucherToTallyAsync(
                                        company.Name,
                                        normalizedType,
                                        voucherDate,
                                        partyLedger,
                                        amount,
                                        narration,
                                        ledgerEntries.Count > 0 ? ledgerEntries : null,
                                        inventoryEntries.Count > 0 ? inventoryEntries : null,
                                        preferredBusinessLedger,
                                        knownLedgerNames,
                                        company.FinancialYearStart,
                                        company.FinancialYearEnd
                                    );

                                    if (stockRetrySuccess)
                                    {
                                        await _apiClient.UpdatePendingTransactionStatusAsync(transaction.Id, "synced", stockRetryVoucherNumber, null, 0);
                                        await MirrorSuccessfulPendingVoucherAsync(
                                            company,
                                            voucherToken,
                                            normalizedType,
                                            stockRetryVoucherNumber,
                                            voucherDate,
                                            partyLedger,
                                            amount,
                                            narration,
                                            ledgerEntries,
                                            inventoryEntries);
                                        AddLog($"   [RETRY] Created in Tally after stock auto-create: {stockRetryVoucherNumber}");
                                        PublishItemSyncStatus(partyLedger, normalizedType, "Success");
                                        successCount++;
                                        continue;
                                    }

                                    error = stockRetryErrorMessage ?? error;
                                }
                                else
                                {
                                    AddLog($"   [RETRY] Auto-create stock item failed: {stockCreateError ?? "Unknown error"}");
                                }
                            }
                            if (inventoryEntries.Count > 0 && IsNoLineErrorImportError(error) && !IsVoucherDateMissingError(error))
                            {
                                SnapshotLastPushDiagnostics(transaction.Id, attemptNumber, "inventory-no-lineerror");
                                AddLog("   [RETRY] Diagnostic snapshot saved under Logs/last_push_voucher_request_<txn>_a<attempt>_inventory-no-lineerror.xml");

                                if (!allowAccountingFallback)
                                {
                                    AddLog("   [FALLBACK] Inventory push failed without LINEERROR. Accounting fallback is disabled to prevent item/GST loss.");
                                    AddLog("   [FALLBACK] In Tally, open Sales/Purchase in Item Invoice mode and verify common-ledger item allocation if one ledger is used for all items. Or set allow_accounting_fallback=true for ledger-only fallback.");
                                    error = AppendInventoryModeGuidance(error);
                                }
                                else
                                {
                                    var accountingFallbackLedgers = BuildAccountingOnlyFallbackLedgers(
                                        normalizedType,
                                        partyLedger,
                                        amount,
                                        inventoryEntries,
                                        ledgerEntries,
                                        preferredBusinessLedger,
                                        knownLedgerNames);

                                    if (accountingFallbackLedgers.Count > 0)
                                    {
                                        AddLog("   [FALLBACK] Inventory mode failed, accounting fallback applied automatically.");
                                        AddLog($"   [FALLBACK] Retrying as accounting-only voucher with {accountingFallbackLedgers.Count} ledgers...");
                                        var accountingFallbackContext = BuildPendingPushContext(
                                            transaction.Id,
                                            normalizedType + " (acct-fallback)",
                                            partyLedger,
                                            voucherDate,
                                            amount,
                                            new List<VoucherInventoryEntry>(),
                                            accountingFallbackLedgers,
                                            cgstAmount,
                                            sgstAmount,
                                            igstAmount,
                                            cessAmount);

                                        AddLog($"   [PUSH] {accountingFallbackContext}");

                                        var (accountingRetrySuccess, accountingRetryVoucherNumber, accountingRetryErrorMessage) = await _tallyConnector.PushVoucherToTallyAsync(
                                            company.Name,
                                            normalizedType,
                                            voucherDate,
                                            partyLedger,
                                            amount,
                                            narration,
                                            accountingFallbackLedgers,
                                            null,
                                            preferredBusinessLedger,
                                            knownLedgerNames,
                                            company.FinancialYearStart,
                                            company.FinancialYearEnd
                                        );

                                        if (accountingRetrySuccess)
                                        {
                                            await _apiClient.UpdatePendingTransactionStatusAsync(transaction.Id, "synced", accountingRetryVoucherNumber, null, 0);
                                            await MirrorSuccessfulPendingVoucherAsync(
                                                company,
                                                voucherToken,
                                                normalizedType,
                                                accountingRetryVoucherNumber,
                                                voucherDate,
                                                partyLedger,
                                                amount,
                                                narration,
                                                accountingFallbackLedgers,
                                                new List<VoucherInventoryEntry>());
                                            AddLog($"   [FALLBACK] Created in Tally after accounting fallback: {accountingRetryVoucherNumber}");
                                            AddLog("   [FALLBACK] Note: accounting fallback created a ledger-only voucher; item lines may not appear in Tally inventory view.");
                                            PublishItemSyncStatus(partyLedger, normalizedType, "Success");
                                            successCount++;
                                            continue;
                                        }

                                        error = accountingRetryErrorMessage ?? error;
                                    }
                                }
                            }
                            var failureClassification = ClassifyPendingPushFailure(
                                normalizedType,
                                partyLedger,
                                inventoryEntries.Count > 0,
                                allowAccountingFallback,
                                error,
                                validationResult);

                            SnapshotLastPushDiagnostics(transaction.Id, attemptNumber, failureClassification.Code);

                            var nextAttempt = currentAttempt + 1;
                            var nextStatus = nextAttempt < MaxPendingPushRetries ? "pending" : "failed";
                            var retryError = AppendRetryMetadata(BuildStoredPushError(failureClassification.Message, error), nextAttempt);

                            await _apiClient.UpdatePendingTransactionStatusAsync(
                                transaction.Id,
                                nextStatus,
                                null,
                                retryError,
                                nextAttempt);

                            AddLog($"   [FINAL ERROR] Failed attempt {nextAttempt}/{MaxPendingPushRetries}: {failureClassification.Message}");
                            AddLog($"   [FINAL ERROR] Failure context: {pushContext}");
                            if (!string.IsNullOrWhiteSpace(error)
                                && !string.Equals(failureClassification.Message, error.Trim(), StringComparison.OrdinalIgnoreCase))
                            {
                                AddLog($"   [FINAL ERROR] Raw Tally response: {error}");
                            }

                            if (failureClassification.Code == "missing-stock-item")
                            {
                                AddLog("   [FINAL ERROR] Create or sync the missing stock master in Tally, then retry.");
                            }
                            else if (failureClassification.Code == "missing-ledger" || failureClassification.Code == "missing-party-ledger")
                            {
                                AddLog("   [FINAL ERROR] Create or align the missing ledger in Tally, then retry.");
                            }
                            else if (failureClassification.Code == "voucher-type-mode-mismatch" || failureClassification.Code == "tally-silent-rejection")
                            {
                                AddLog("   [FINAL ERROR] Check the saved diagnostic XML files to compare inventory mode vs fallback mode behavior.");
                            }

                            AddLog(nextStatus == "pending"
                                ? $"   [RETRY] Transaction kept in queue for automatic retry {nextAttempt + 1}/{MaxPendingPushRetries}."
                                : "   [FINAL ERROR] Retry limit reached; transaction marked as failed.");

                            PublishItemSyncStatus(partyLedger, normalizedType, "Error", retryError);
                            failCount++;
                        }
                    }
                    catch (Exception ex)
                    {
                        var nextAttempt = currentAttempt + 1;
                        var nextStatus = nextAttempt < MaxPendingPushRetries ? "pending" : "failed";
                        var retryError = AppendRetryMetadata(ex.Message, nextAttempt);

                        await _apiClient.UpdatePendingTransactionStatusAsync(
                            transaction.Id,
                            nextStatus,
                            null,
                            retryError,
                            nextAttempt);

                        AddLog($"   Failed attempt {nextAttempt}/{MaxPendingPushRetries}: {ex.Message}");
                        PublishItemSyncStatus(transaction.Id, transaction.TransactionType, "Error", ex.Message);
                        failCount++;
                    }

                    await Task.Delay(200);
                }

                if (successCount > 0)
                {
                    AddLog($"Two-Way Sync: {successCount} entries pushed to Tally");
                }

                if (failCount > 0)
                {
                    AddLog($"Two-Way Sync: {failCount} entries failed (retry queued where attempts remain)");
                }
            }
            catch (Exception ex)
            {
                SyncLogger.Log($"ProcessPendingTransactionsAsync error: {ex.Message}");
            }
        }

        private void UpsertStockItemMetaCache(IEnumerable<StockItem>? stockItems)
        {
            if (stockItems == null)
            {
                return;
            }

            foreach (var stockItem in stockItems)
            {
                if (stockItem == null || string.IsNullOrWhiteSpace(stockItem.Name))
                {
                    continue;
                }

                var normalizedName = stockItem.Name.Trim();
                _stockItemMetaCache[normalizedName] = new StockItemPushMeta
                {
                    Name = normalizedName,
                    GstRate = Math.Abs(stockItem.GstRate),
                    HsnCode = (stockItem.HsnCode ?? string.Empty).Trim(),
                    Unit = (stockItem.BaseUnit ?? string.Empty).Trim()
                };
            }
        }

        private (int TaxRatesFilled, int HsnFilled, int UnitsFilled) ApplyStockItemMetaFallbacks(List<VoucherInventoryEntry> inventoryEntries)
        {
            if (inventoryEntries == null || inventoryEntries.Count == 0 || _stockItemMetaCache.Count == 0)
            {
                return (0, 0, 0);
            }

            int taxRatesFilled = 0;
            int hsnFilled = 0;
            int unitsFilled = 0;

            foreach (var item in inventoryEntries)
            {
                if (item == null || string.IsNullOrWhiteSpace(item.StockItemName))
                {
                    continue;
                }

                if (!_stockItemMetaCache.TryGetValue(item.StockItemName.Trim(), out var meta) || meta == null)
                {
                    continue;
                }

                if ((!item.TaxRate.HasValue || item.TaxRate.Value <= 0m) && meta.GstRate > 0m)
                {
                    item.TaxRate = meta.GstRate;
                    if (string.IsNullOrWhiteSpace(item.Taxability))
                    {
                        item.Taxability = "Taxable";
                    }
                    taxRatesFilled++;
                }

                if (string.IsNullOrWhiteSpace(item.HsnCode) && !string.IsNullOrWhiteSpace(meta.HsnCode))
                {
                    item.HsnCode = meta.HsnCode;
                    hsnFilled++;
                }

                if (string.IsNullOrWhiteSpace(item.Unit) && !string.IsNullOrWhiteSpace(meta.Unit))
                {
                    item.Unit = meta.Unit;
                    unitsFilled++;
                }
            }

            return (taxRatesFilled, hsnFilled, unitsFilled);
        }

        private static string BuildFinancialYearLabel(DateTime voucherDate)
        {
            var fyStartYear = voucherDate.Month >= 4 ? voucherDate.Year : voucherDate.Year - 1;
            return $"{fyStartYear}-{(fyStartYear + 1) % 100:00}";
        }

        private static string FormatTopNames(IEnumerable<string> names, int maxCount = 5)
        {
            var distinct = names
                .Where(name => !string.IsNullOrWhiteSpace(name))
                .Select(name => name.Trim())
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList();

            if (distinct.Count == 0)
            {
                return string.Empty;
            }

            var head = string.Join(", ", distinct.Take(maxCount));
            return distinct.Count > maxCount ? head + $" +{distinct.Count - maxCount} more" : head;
        }

        private (
            bool PartyLedgerMissing,
            bool VoucherTypeMissing,
            List<string> MissingLedgers,
            List<string> MissingStockItems,
            List<string> MissingUnits
        ) InspectPendingVoucherMasters(
            string voucherType,
            string partyLedger,
            string? preferredBusinessLedger,
            IEnumerable<VoucherLedgerEntry> ledgerEntries,
            IEnumerable<VoucherInventoryEntry> inventoryEntries,
            HashSet<string>? knownLedgerNames,
            HashSet<string>? knownVoucherTypeNames,
            HashSet<string>? knownUnitNames)
        {
            var missingLedgers = new List<string>();
            var missingStockItems = new List<string>();
            var missingUnits = new List<string>();

            bool partyLedgerMissing = !string.IsNullOrWhiteSpace(partyLedger)
                && knownLedgerNames != null
                && knownLedgerNames.Count > 0
                && !knownLedgerNames.Contains(partyLedger.Trim());

            bool voucherTypeMissing = !string.IsNullOrWhiteSpace(voucherType)
                && knownVoucherTypeNames != null
                && knownVoucherTypeNames.Count > 0
                && !knownVoucherTypeNames.Contains(voucherType.Trim());

            if (!string.IsNullOrWhiteSpace(preferredBusinessLedger)
                && knownLedgerNames != null
                && knownLedgerNames.Count > 0
                && !knownLedgerNames.Contains(preferredBusinessLedger.Trim()))
            {
                missingLedgers.Add(preferredBusinessLedger.Trim());
            }

            if (knownLedgerNames != null && knownLedgerNames.Count > 0)
            {
                missingLedgers.AddRange(
                    ledgerEntries
                        .Where(entry => entry != null && !string.IsNullOrWhiteSpace(entry.LedgerName))
                        .Select(entry => entry.LedgerName!.Trim())
                        .Where(name => !string.Equals(name, partyLedger?.Trim(), StringComparison.OrdinalIgnoreCase))
                        .Where(name => !knownLedgerNames.Contains(name))
                );
            }

            missingStockItems.AddRange(
                inventoryEntries
                    .Where(entry => entry != null && !string.IsNullOrWhiteSpace(entry.StockItemName))
                    .Select(entry => entry.StockItemName!.Trim())
                    .Where(name => !_stockItemMetaCache.ContainsKey(name))
            );

            if (knownUnitNames != null && knownUnitNames.Count > 0)
            {
                missingUnits.AddRange(
                    inventoryEntries
                        .Where(entry => entry != null && !string.IsNullOrWhiteSpace(entry.Unit))
                        .Select(entry => entry.Unit!.Trim())
                        .Where(unit => !knownUnitNames.Contains(unit))
                );
            }

            return (
                partyLedgerMissing,
                voucherTypeMissing,
                missingLedgers.Distinct(StringComparer.OrdinalIgnoreCase).ToList(),
                missingStockItems.Distinct(StringComparer.OrdinalIgnoreCase).ToList(),
                missingUnits.Distinct(StringComparer.OrdinalIgnoreCase).ToList());
        }

        private void LogPendingVoucherValidation(
            string voucherType,
            string partyLedger,
            DateTime voucherDate,
            decimal amount,
            List<VoucherInventoryEntry> inventoryEntries,
            List<VoucherLedgerEntry> ledgerEntries,
            Company company,
            (
                bool PartyLedgerMissing,
                bool VoucherTypeMissing,
                List<string> MissingLedgers,
                List<string> MissingStockItems,
                List<string> MissingUnits
            ) validationResult)
        {
            AddLog($"   [VALIDATION] type={voucherType}, party={partyLedger}, amount={amount:0.##}, items={inventoryEntries.Count}, ledgers={ledgerEntries.Count}");
            AddLog($"   [PERIOD] Voucher date {voucherDate:dd-MMM-yyyy} mapped to FY {BuildFinancialYearLabel(voucherDate)}.");

            if (company.BooksStartDate.HasValue && IsValidVoucherDate(company.BooksStartDate.Value))
            {
                AddLog($"   [PERIOD] Books beginning from {company.BooksStartDate.Value:dd-MMM-yyyy}.");
            }

            if (company.FinancialYearStart.HasValue && company.FinancialYearEnd.HasValue
                && IsValidVoucherDate(company.FinancialYearStart.Value) && IsValidVoucherDate(company.FinancialYearEnd.Value))
            {
                bool coversVoucherDate = voucherDate >= company.FinancialYearStart.Value.Date && voucherDate <= company.FinancialYearEnd.Value.Date;
                AddLog(coversVoucherDate
                    ? $"   [PERIOD] Company metadata period {company.FinancialYearStart.Value:dd-MMM-yyyy} to {company.FinancialYearEnd.Value:dd-MMM-yyyy} covers voucher date."
                    : $"   [PERIOD] Company metadata period {company.FinancialYearStart.Value:dd-MMM-yyyy} to {company.FinancialYearEnd.Value:dd-MMM-yyyy} does not cover voucher date. Dynamic request period will be used.");
            }
            else
            {
                AddLog("   [PERIOD] Active Tally period could not be read from metadata; dynamic request period will be used.");
            }

            AddLog("   [PERIOD] Automatic request-level period handling is enabled for voucher push.");

            if (!validationResult.PartyLedgerMissing
                && !validationResult.VoucherTypeMissing
                && validationResult.MissingLedgers.Count == 0
                && validationResult.MissingStockItems.Count == 0
                && validationResult.MissingUnits.Count == 0)
            {
                AddLog("   [VALIDATION] Masters look ready based on cached Tally ledgers, voucher types, stock items, and units.");
                return;
            }

            if (validationResult.PartyLedgerMissing)
            {
                AddLog($"   [VALIDATION] Missing Party Ledger: {partyLedger}");
            }

            if (validationResult.VoucherTypeMissing)
            {
                AddLog($"   [VALIDATION] Missing Voucher Type: {voucherType}");
            }

            if (validationResult.MissingLedgers.Count > 0)
            {
                AddLog($"   [VALIDATION] Missing Ledger: {FormatTopNames(validationResult.MissingLedgers)}");
            }

            if (validationResult.MissingStockItems.Count > 0)
            {
                AddLog($"   [VALIDATION] Missing Stock Item: {FormatTopNames(validationResult.MissingStockItems)}");
            }

            if (validationResult.MissingUnits.Count > 0)
            {
                AddLog($"   [VALIDATION] Missing Unit: {FormatTopNames(validationResult.MissingUnits)}");
            }
        }

        private static (string Code, string Message) ClassifyPendingPushFailure(
            string voucherType,
            string partyLedger,
            bool hasInventory,
            bool allowAccountingFallback,
            string? rawError,
            (
                bool PartyLedgerMissing,
                bool VoucherTypeMissing,
                List<string> MissingLedgers,
                List<string> MissingStockItems,
                List<string> MissingUnits
            ) validationResult)
        {
            if (IsVoucherDateMissingError(rawError))
            {
                return ("period-mismatch", $"{voucherType} voucher rejected because voucher date/period is not allowed by Tally.");
            }

            if (TryExtractMissingStockItemName(rawError, out var missingStockItemName))
            {
                return ("missing-stock-item", $"{voucherType} voucher blocked because stock item '{missingStockItemName}' was not found in Tally.");
            }

            if (TryExtractMissingLedgerName(rawError, out var missingLedgerName))
            {
                return ("missing-ledger", $"{voucherType} voucher blocked because ledger '{missingLedgerName}' was not found in Tally.");
            }

            if (validationResult.PartyLedgerMissing)
            {
                return ("missing-party-ledger", $"{voucherType} voucher blocked because party ledger '{partyLedger}' is missing in Tally.");
            }

            if (validationResult.MissingStockItems.Count > 0)
            {
                return ("missing-stock-item", $"{voucherType} voucher blocked because stock item master is missing in Tally: {FormatTopNames(validationResult.MissingStockItems)}.");
            }

            if (validationResult.MissingLedgers.Count > 0)
            {
                return ("missing-ledger", $"{voucherType} voucher blocked because ledger master is missing in Tally: {FormatTopNames(validationResult.MissingLedgers)}.");
            }

            if (validationResult.VoucherTypeMissing)
            {
                return ("missing-voucher-type", $"{voucherType} voucher type is not available in Tally.");
            }

            if (validationResult.MissingUnits.Count > 0)
            {
                return ("missing-unit", $"{voucherType} voucher may fail because unit master is missing or mismatched: {FormatTopNames(validationResult.MissingUnits)}.");
            }

            var normalized = string.IsNullOrWhiteSpace(rawError) ? string.Empty : rawError.Trim();
            if (!string.IsNullOrWhiteSpace(normalized)
                && normalized.IndexOf("gst", StringComparison.OrdinalIgnoreCase) >= 0
                && (normalized.IndexOf("structure", StringComparison.OrdinalIgnoreCase) >= 0
                    || normalized.IndexOf("taxability", StringComparison.OrdinalIgnoreCase) >= 0
                    || normalized.IndexOf("hsn", StringComparison.OrdinalIgnoreCase) >= 0))
            {
                return ("gst-structure-mismatch", $"{voucherType} voucher was rejected because GST/inventory structure is incompatible with current Tally configuration.");
            }

            if (!string.IsNullOrWhiteSpace(normalized)
                && normalized.IndexOf("xml", StringComparison.OrdinalIgnoreCase) >= 0
                && (normalized.IndexOf("malformed", StringComparison.OrdinalIgnoreCase) >= 0
                    || normalized.IndexOf("invalid", StringComparison.OrdinalIgnoreCase) >= 0
                    || normalized.IndexOf("parse", StringComparison.OrdinalIgnoreCase) >= 0))
            {
                return ("xml-malformed", $"{voucherType} voucher XML was rejected by Tally as malformed or invalid.");
            }

            if (hasInventory && IsNoLineErrorImportError(normalized))
            {
                var message = allowAccountingFallback
                    ? $"{voucherType} voucher was silently rejected in inventory mode. Accounting fallback was attempted automatically but Tally still rejected the voucher."
                    : $"{voucherType} voucher was silently rejected in inventory mode. Tally likely rejected item-invoice or common-ledger configuration, and accounting fallback was disabled.";
                return ("voucher-type-mode-mismatch", message);
            }

            if (IsNoLineErrorImportError(normalized))
            {
                return ("tally-silent-rejection", $"{voucherType} voucher was rejected by Tally without LINEERROR. Review saved diagnostic XML files.");
            }

            return ("unknown-exception", string.IsNullOrWhiteSpace(normalized)
                ? $"{voucherType} voucher failed for an unknown reason."
                : normalized);
        }

        private static string BuildStoredPushError(string classifiedReason, string? rawError)
        {
            var normalizedRaw = string.IsNullOrWhiteSpace(rawError) ? string.Empty : rawError.Trim();
            if (string.IsNullOrWhiteSpace(normalizedRaw)
                || string.Equals(classifiedReason.Trim(), normalizedRaw, StringComparison.OrdinalIgnoreCase))
            {
                return classifiedReason.Trim();
            }

            return $"{classifiedReason.Trim()} Raw Tally response: {normalizedRaw}";
        }

        private static bool? GetAccountingFallbackPreference(JToken? voucherToken)
        {
            var directPreference = GetTokenBool(
                voucherToken,
                "allow_accounting_fallback",
                "allowAccountingFallback",
                "force_accounting_fallback",
                "forceAccountingFallback",
                "use_accounting_fallback",
                "useAccountingFallback");

            if (directPreference.HasValue)
            {
                return directPreference.Value;
            }

            var disableFallback = GetTokenBool(
                voucherToken,
                "disable_accounting_fallback",
                "disableAccountingFallback",
                "prevent_accounting_fallback",
                "preventAccountingFallback");

            return disableFallback == true ? false : null;
        }
        private static string AppendInventoryModeGuidance(string? errorMessage)
        {
            const string guidance = "Inventory lines/GST were not posted. Tally rejected invoice-mode inventory import. In Tally, open the Sales/Purchase voucher in Item Invoice mode; if all items post to one ledger like PURCHASE A\\C, also enable the common-ledger item allocation setting. Otherwise set allow_accounting_fallback=true in voucher_data for ledger-only posting.";

            var baseMessage = string.IsNullOrWhiteSpace(errorMessage)
                ? "Inventory voucher import failed."
                : errorMessage.Trim();

            if (baseMessage.IndexOf("Inventory lines/GST were not posted", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return baseMessage;
            }

            return baseMessage + " " + guidance;
        }

        private static void SnapshotLastPushDiagnostics(string transactionId, int attemptNumber, string stage)
        {
            try
            {
                var logDir = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "Logs");
                if (!Directory.Exists(logDir))
                {
                    return;
                }

                var safeTxn = SanitizeFileToken(transactionId);
                var safeStage = SanitizeFileToken(stage);

                void CopyIfExists(string sourceFileName)
                {
                    var sourcePath = Path.Combine(logDir, sourceFileName);
                    if (!File.Exists(sourcePath))
                    {
                        return;
                    }

                    var destinationFileName = $"{Path.GetFileNameWithoutExtension(sourceFileName)}_{safeTxn}_a{attemptNumber}_{safeStage}{Path.GetExtension(sourceFileName)}";
                    var destinationPath = Path.Combine(logDir, destinationFileName);
                    File.Copy(sourcePath, destinationPath, true);
                }

                CopyIfExists("last_push_voucher_request.xml");
                CopyIfExists("last_push_voucher_response.xml");
                SyncLogger.Log($"Saved push diagnostics snapshot for {safeTxn} attempt {attemptNumber} ({safeStage}).");
            }
            catch
            {
                // Diagnostics snapshot is best-effort only.
            }
        }

        private static string SanitizeFileToken(string value)
        {
            if (string.IsNullOrWhiteSpace(value))
            {
                return "na";
            }

            var cleaned = new string(value
                .Where(ch => char.IsLetterOrDigit(ch) || ch == '-' || ch == '_')
                .ToArray());

            if (string.IsNullOrWhiteSpace(cleaned))
            {
                return "na";
            }

            return cleaned.Length > 32 ? cleaned.Substring(0, 32) : cleaned;
        }

        private static JToken? ToJToken(object? value)
        {
            if (value == null)
            {
                return null;
            }

            if (value is JToken token)
            {
                return NormalizeEmbeddedJsonToken(token);
            }

            if (value is string text)
            {
                var parsed = TryParseJsonToken(text);
                if (parsed != null)
                {
                    return parsed;
                }
            }

            try
            {
                return NormalizeEmbeddedJsonToken(JToken.FromObject(value));
            }
            catch
            {
                return null;
            }
        }

        private static JToken? TryParseJsonToken(string? value)
        {
            if (string.IsNullOrWhiteSpace(value))
            {
                return null;
            }

            var trimmed = value.Trim();
            if ((!trimmed.StartsWith("{", StringComparison.Ordinal) || !trimmed.EndsWith("}", StringComparison.Ordinal))
                && (!trimmed.StartsWith("[", StringComparison.Ordinal) || !trimmed.EndsWith("]", StringComparison.Ordinal)))
            {
                return null;
            }

            try
            {
                return JToken.Parse(trimmed);
            }
            catch
            {
                return null;
            }
        }

        private static JToken? NormalizeEmbeddedJsonToken(JToken? token)
        {
            if (token == null || token.Type == JTokenType.Null)
            {
                return token;
            }

            if (token is JValue value && value.Type == JTokenType.String)
            {
                var parsed = TryParseJsonToken(value.ToString());
                if (parsed != null)
                {
                    return parsed;
                }
            }

            return token;
        }
        private static string? GetTokenString(JToken? token, params string[] keys)
        {
            if (token == null)
            {
                return null;
            }

            foreach (var key in keys)
            {
                var candidate = token[key];
                if (candidate == null || candidate.Type == JTokenType.Null)
                {
                    continue;
                }

                var text = candidate.ToString().Trim();
                if (!string.IsNullOrWhiteSpace(text))
                {
                    return text;
                }
            }

            return null;
        }

        private static decimal? GetTokenDecimal(JToken? token, params string[] keys)
        {
            if (token == null)
            {
                return null;
            }

            foreach (var key in keys)
            {
                var candidate = token[key];
                if (candidate == null || candidate.Type == JTokenType.Null)
                {
                    continue;
                }

                var text = candidate.ToString().Trim();
                var normalizedText = text
                    .Replace(",", string.Empty)
                    .Replace("%", string.Empty)
                    .Replace("\u20B9", string.Empty)
                    .Replace("rs.", string.Empty, StringComparison.OrdinalIgnoreCase)
                    .Replace("rs", string.Empty, StringComparison.OrdinalIgnoreCase)
                    .Trim();

                if (decimal.TryParse(text, NumberStyles.Any, CultureInfo.InvariantCulture, out var value)
                    || decimal.TryParse(text, NumberStyles.Any, CultureInfo.CurrentCulture, out value)
                    || decimal.TryParse(normalizedText, NumberStyles.Any, CultureInfo.InvariantCulture, out value)
                    || decimal.TryParse(normalizedText, NumberStyles.Any, CultureInfo.CurrentCulture, out value))
                {
                    return value;
                }
            }

            return null;
        }
        private static DateTime? GetTokenDate(JToken? token, params string[] keys)
        {
            if (token == null)
            {
                return null;
            }

            foreach (var key in keys)
            {
                var candidate = token[key];
                if (candidate == null || candidate.Type == JTokenType.Null)
                {
                    continue;
                }

                if (candidate.Type == JTokenType.Date)
                {
                    var dateValue = candidate.Value<DateTime>();
                    if (IsValidVoucherDate(dateValue))
                    {
                        return dateValue.Date;
                    }

                    continue;
                }

                if ((candidate.Type == JTokenType.Integer || candidate.Type == JTokenType.Float)
                    && long.TryParse(candidate.ToString(), NumberStyles.Any, CultureInfo.InvariantCulture, out var epochNumber))
                {
                    var epochDate = TryParseUnixDate(epochNumber);
                    if (epochDate.HasValue)
                    {
                        return epochDate.Value.Date;
                    }
                }

                if (TryParseFlexibleDate(candidate.ToString(), out var parsedDate))
                {
                    return parsedDate.Date;
                }
            }

            return null;
        }

        private static bool TryParseFlexibleDate(string? value, out DateTime parsedDate)
        {
            parsedDate = default;
            if (string.IsNullOrWhiteSpace(value))
            {
                return false;
            }

            var text = value.Trim();
            if (long.TryParse(text, NumberStyles.Integer, CultureInfo.InvariantCulture, out var epochNumber))
            {
                var epochDate = TryParseUnixDate(epochNumber);
                if (epochDate.HasValue)
                {
                    parsedDate = epochDate.Value;
                    return true;
                }
            }

            string[] formats =
            {
                "yyyy-MM-dd",
                "yyyy/MM/dd",
                "dd-MM-yyyy",
                "dd/MM/yyyy",
                "MM/dd/yyyy",
                "yyyyMMdd",
                "ddMMyyyy",
                "dd-MMM-yyyy",
                "dd MMM yyyy",
                "yyyy-MM-ddTHH:mm:ss",
                "yyyy-MM-ddTHH:mm:ssZ",
                "yyyy-MM-ddTHH:mm:ss.fffZ",
                "yyyy-MM-ddTHH:mm:ss.fffffffZ",
                "yyyy-MM-ddTHH:mm:ssK",
                "yyyy-MM-ddTHH:mm:ss.fffK",
                "o"
            };

            if (DateTime.TryParseExact(text, formats, CultureInfo.InvariantCulture, DateTimeStyles.AllowWhiteSpaces, out parsedDate)
                || DateTime.TryParse(text, CultureInfo.InvariantCulture, DateTimeStyles.AllowWhiteSpaces, out parsedDate)
                || DateTime.TryParse(text, CultureInfo.CurrentCulture, DateTimeStyles.AllowWhiteSpaces, out parsedDate))
            {
                if (IsValidVoucherDate(parsedDate))
                {
                    parsedDate = parsedDate.Date;
                    return true;
                }
            }

            return false;
        }

        private static DateTime? TryParseUnixDate(long rawValue)
        {
            if (rawValue <= 0)
            {
                return null;
            }

            try
            {
                DateTime date;
                // >= 13 digits is typically Unix milliseconds
                if (rawValue >= 1000000000000)
                {
                    date = DateTimeOffset.FromUnixTimeMilliseconds(rawValue).LocalDateTime;
                }
                else
                {
                    date = DateTimeOffset.FromUnixTimeSeconds(rawValue).LocalDateTime;
                }

                return IsValidVoucherDate(date) ? date.Date : null;
            }
            catch
            {
                return null;
            }
        }

        private static bool IsValidVoucherDate(DateTime value)
        {
            if (value == DateTime.MinValue || value == DateTime.MaxValue)
            {
                return false;
            }

            var year = value.Year;
            return year >= 1900 && year <= DateTime.Today.Year + 10;
        }
        private static string? GetEducationalModeDateRestrictionHint(DateTime voucherDate)
        {
            int day = voucherDate.Day;
            if (day == 1 || day == 2 || day == 31)
            {
                return null;
            }

            return $"If Tally is running in Educational Mode, voucher dates are allowed only on the 1st, 2nd, and 31st of a month. {voucherDate:dd-MMM-yyyy} is restricted in EDU mode.";
        }

        private static bool IsVoucherDateMissingError(string? message)
        {
            if (string.IsNullOrWhiteSpace(message))
            {
                return false;
            }

            var normalized = message.Trim();
            var genericCauseIndex = normalized.IndexOf("Common causes:", StringComparison.OrdinalIgnoreCase);
            if (genericCauseIndex >= 0)
            {
                normalized = normalized[..genericCauseIndex].TrimEnd();
            }

            if (string.IsNullOrWhiteSpace(normalized))
            {
                return false;
            }

            string[] explicitDateSignals =
            {
                "voucher date is missing",
                "voucher date missing",
                "voucher date is invalid",
                "voucher date invalid",
                "voucher date is not within",
                "voucher date should be between",
                "voucher date is outside",
                "voucher date outside",
                "voucher date is before",
                "voucher date is beyond",
                "date is outside the books",
                "date is not within the books",
                "date is outside the current period",
                "date is not within the current period",
                "before books beginning from",
                "prior to books beginning from"
            };

            return explicitDateSignals.Any(signal =>
                normalized.IndexOf(signal, StringComparison.OrdinalIgnoreCase) >= 0);
        }

        private static bool IsNoLineErrorImportError(string? message)
        {
            if (string.IsNullOrWhiteSpace(message))
            {
                return false;
            }

            var normalized = message.Trim();
            return normalized.IndexOf("No LINEERROR returned", StringComparison.OrdinalIgnoreCase) >= 0
                || (normalized.IndexOf("Created=0", StringComparison.OrdinalIgnoreCase) >= 0
                    && normalized.IndexOf("Altered=0", StringComparison.OrdinalIgnoreCase) >= 0
                    && normalized.IndexOf("Errors=0", StringComparison.OrdinalIgnoreCase) >= 0);
        }
        private static bool TryExtractMissingStockItemName(string? message, out string stockItemName)
        {
            stockItemName = string.Empty;
            if (string.IsNullOrWhiteSpace(message))
            {
                return false;
            }

            var match = MissingStockItemRegex.Match(message);
            if (!match.Success)
            {
                return false;
            }

            var extracted = match.Groups["name"]?.Value?.Trim();
            if (string.IsNullOrWhiteSpace(extracted))
            {
                return false;
            }

            stockItemName = extracted;
            return true;
        }
        private static bool TryExtractMissingLedgerName(string? message, out string ledgerName)
        {
            ledgerName = string.Empty;
            if (string.IsNullOrWhiteSpace(message))
            {
                return false;
            }

            var match = MissingLedgerRegex.Match(message);
            if (!match.Success)
            {
                return false;
            }

            var extracted = match.Groups["name"]?.Value?.Trim();
            if (string.IsNullOrWhiteSpace(extracted))
            {
                return false;
            }

            ledgerName = extracted;
            return true;
        }
        private static bool? GetTokenBool(JToken? token, params string[] keys)
        {
            if (token == null)
            {
                return null;
            }

            foreach (var key in keys)
            {
                var candidate = token[key];
                if (candidate == null || candidate.Type == JTokenType.Null)
                {
                    continue;
                }

                if (candidate.Type == JTokenType.Boolean)
                {
                    return candidate.Value<bool>();
                }

                var text = candidate.ToString().Trim();
                if (bool.TryParse(text, out var boolValue))
                {
                    return boolValue;
                }

                if (text.Equals("dr", StringComparison.OrdinalIgnoreCase)
                    || text.Equals("debit", StringComparison.OrdinalIgnoreCase))
                {
                    return true;
                }

                if (text.Equals("cr", StringComparison.OrdinalIgnoreCase)
                    || text.Equals("credit", StringComparison.OrdinalIgnoreCase))
                {
                    return false;
                }
            }

            return null;
        }

        private static List<JToken> GetTokenArrayItems(JToken? token, params string[] keys)
        {
            var output = new List<JToken>();
            if (token == null)
            {
                return output;
            }

            foreach (var key in keys)
            {
                var candidate = NormalizeEmbeddedJsonToken(token[key]);
                if (candidate == null || candidate.Type == JTokenType.Null)
                {
                    continue;
                }

                if (candidate is JArray array)
                {
                    foreach (var item in array)
                    {
                        var normalizedItem = NormalizeEmbeddedJsonToken(item);
                        if (normalizedItem != null && normalizedItem.Type != JTokenType.Null)
                        {
                            output.Add(normalizedItem);
                        }
                    }
                }
                else if (candidate is JObject obj)
                {
                    output.Add(obj);
                }
            }

            return output;
        }

        private static List<string> GetPresentTokenKeys(JToken? token, params string[] keys)
        {
            var present = new List<string>();
            if (token == null)
            {
                return present;
            }

            foreach (var key in keys)
            {
                var candidate = NormalizeEmbeddedJsonToken(token[key]);
                if (candidate == null || candidate.Type == JTokenType.Null)
                {
                    continue;
                }

                bool hasValue = candidate switch
                {
                    JArray array => array.Count > 0,
                    JObject obj => obj.Properties().Any(),
                    JValue value => !string.IsNullOrWhiteSpace(value.ToString()),
                    _ => !string.IsNullOrWhiteSpace(candidate.ToString())
                };

                if (hasValue)
                {
                    present.Add(key);
                }
            }

            return present;
        }

        private static List<VoucherInventoryEntry> ExtractInventoryEntries(JToken? voucherToken)
        {
            var rows = GetTokenArrayItems(
                voucherToken,
                "items",
                "stock_entries",
                "inventory_entries",
                "stockEntries",
                "inventoryEntries",
                "sales_items",
                "purchase_items",
                "line_items",
                "lineItems");
            var output = new List<VoucherInventoryEntry>();

            foreach (var row in rows)
            {
                var stockName = GetTokenString(row, "stock_item_name", "stock_item", "item_name", "product_name", "description", "name", "item");
                if (string.IsNullOrWhiteSpace(stockName))
                {
                    continue;
                }

                var qty = GetTokenDecimal(row, "quantity", "qty") ?? 0m;
                var rate = GetTokenDecimal(row, "rate", "price", "unit_price", "unitPrice") ?? 0m;
                var amount = GetTokenDecimal(row, "amount", "total_amount", "total", "totalAmount", "baseAmount", "line_total", "gross_amount", "lineAmount") ?? 0m;

                if (amount <= 0 && qty > 0 && rate > 0)
                {
                    amount = qty * rate;
                }

                if (rate <= 0 && qty > 0 && amount > 0)
                {
                    rate = amount / qty;
                }

                if (qty <= 0 && rate > 0 && amount > 0)
                {
                    qty = amount / rate;
                }

                if (qty <= 0 && amount > 0)
                {
                    qty = 1m;
                }

                if (amount <= 0)
                {
                    continue;
                }

                var taxRate = GetTokenDecimal(row, "tax_rate", "gst_rate", "gstRate", "gst_percent", "gstPercent", "tax_percent", "gst", "rate_of_tax_calculation");
                var lineTaxAmount = Math.Abs(
                    (GetTokenDecimal(row, "cgst_amount", "cgst") ?? 0m)
                    + (GetTokenDecimal(row, "sgst_amount", "sgst") ?? 0m)
                    + (GetTokenDecimal(row, "igst_amount", "igst") ?? 0m)
                    + (GetTokenDecimal(row, "cess_amount", "cess") ?? 0m));

                if ((!taxRate.HasValue || taxRate.Value <= 0m) && lineTaxAmount > 0m && amount > 0m)
                {
                    taxRate = Math.Round((lineTaxAmount / Math.Abs(amount)) * 100m, 2, MidpointRounding.AwayFromZero);
                }

                var taxability = GetTokenString(row, "taxability");
                if (string.IsNullOrWhiteSpace(taxability) && taxRate.HasValue && taxRate.Value > 0m)
                {
                    taxability = "Taxable";
                }

                output.Add(new VoucherInventoryEntry
                {
                    StockItemName = stockName,
                    Quantity = Math.Abs(qty),
                    Unit = GetTokenString(row, "unit", "uom", "base_unit") ?? "Nos",
                    Rate = Math.Abs(rate),
                    Amount = Math.Abs(amount),
                    DiscountPercent = Math.Abs(GetTokenDecimal(row, "discount_percent", "discountPercent", "discount") ?? 0m),
                    HsnCode = GetTokenString(row, "hsn_code", "hsn", "hsnCode", "hsn_sac", "hsnSac", "hsn_or_sac_code"),
                    TaxRate = taxRate,
                    Taxability = taxability
                });
            }

            return output;
        }
        private static List<VoucherLedgerEntry> ExtractLedgerEntries(JToken? voucherToken)
        {
            var rows = GetTokenArrayItems(voucherToken, "ledger_entries", "ledgerEntries", "entries");
            var output = new List<VoucherLedgerEntry>();

            foreach (var row in rows)
            {
                var ledgerName = GetTokenString(row, "ledger_name", "ledgerName", "name", "account_name", "accountName");
                if (string.IsNullOrWhiteSpace(ledgerName))
                {
                    continue;
                }

                var rawAmount = GetTokenDecimal(row, "amount", "total_amount", "total", "value") ?? 0m;
                if (rawAmount == 0)
                {
                    continue;
                }

                var isDebit = GetTokenBool(row, "is_debit", "isDebit");
                if (!isDebit.HasValue)
                {
                    var typeText = GetTokenString(row, "type", "dr_cr", "entry_type");
                    if (!string.IsNullOrWhiteSpace(typeText))
                    {
                        if (typeText.StartsWith("D", StringComparison.OrdinalIgnoreCase))
                        {
                            isDebit = true;
                        }
                        else if (typeText.StartsWith("C", StringComparison.OrdinalIgnoreCase))
                        {
                            isDebit = false;
                        }
                    }
                }

                var debit = isDebit ?? (rawAmount < 0);
                var signedAmount = debit ? -Math.Abs(rawAmount) : Math.Abs(rawAmount);

                output.Add(new VoucherLedgerEntry
                {
                    LedgerName = ledgerName,
                    Amount = signedAmount,
                    IsDebit = debit
                });
            }

            return output;
        }
        private static List<VoucherLedgerEntry> BuildInventoryVoucherLedgerFallbacks(
            JToken voucherToken,
            string voucherType,
            string partyLedger,
            decimal amount,
            decimal cgstAmount,
            decimal sgstAmount,
            decimal igstAmount,
            decimal cessAmount,
            List<VoucherLedgerEntry> existingEntries,
            IEnumerable<string>? knownLedgerNames)
        {
            var output = new List<VoucherLedgerEntry>();
            if (existingEntries == null)
            {
                return output;
            }

            bool isSalesLike = voucherType.Contains("sale", StringComparison.OrdinalIgnoreCase);
            bool isPurchaseLike = voucherType.Contains("purchase", StringComparison.OrdinalIgnoreCase);
            if (!isSalesLike && !isPurchaseLike)
            {
                return output;
            }

            var knownNames = (knownLedgerNames ?? Enumerable.Empty<string>())
                .Where(name => !string.IsNullOrWhiteSpace(name))
                .Select(name => name.Trim())
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList();

            string ResolveTaxLedgerName(string? configuredLedgerName, string taxKeyword, string defaultSalesLedger, string defaultPurchaseLedger)
            {
                var configured = string.IsNullOrWhiteSpace(configuredLedgerName) ? null : configuredLedgerName.Trim();
                if (!string.IsNullOrWhiteSpace(configured))
                {
                    var exactConfigured = knownNames.FirstOrDefault(name => string.Equals(name, configured, StringComparison.OrdinalIgnoreCase));
                    if (!string.IsNullOrWhiteSpace(exactConfigured))
                    {
                        return exactConfigured;
                    }
                }

                string preferredDefault = isPurchaseLike ? defaultPurchaseLedger : defaultSalesLedger;
                if (knownNames.Count == 0)
                {
                    return configured ?? preferredDefault;
                }

                var exactDefault = knownNames.FirstOrDefault(name => string.Equals(name, preferredDefault, StringComparison.OrdinalIgnoreCase));
                if (!string.IsNullOrWhiteSpace(exactDefault))
                {
                    return exactDefault;
                }

                var exactKeyword = knownNames.FirstOrDefault(name => string.Equals(name, taxKeyword, StringComparison.OrdinalIgnoreCase));
                if (!string.IsNullOrWhiteSpace(exactKeyword))
                {
                    return exactKeyword;
                }

                var keywordMatches = knownNames
                    .Where(name => name.Contains(taxKeyword, StringComparison.OrdinalIgnoreCase))
                    .ToList();

                if (keywordMatches.Count == 0)
                {
                    return configured ?? preferredDefault;
                }

                if (isPurchaseLike)
                {
                    var preferredInput = keywordMatches.FirstOrDefault(name => name.Contains("input", StringComparison.OrdinalIgnoreCase));
                    if (!string.IsNullOrWhiteSpace(preferredInput))
                    {
                        return preferredInput;
                    }

                    var nonOutput = keywordMatches.FirstOrDefault(name => !name.Contains("output", StringComparison.OrdinalIgnoreCase));
                    if (!string.IsNullOrWhiteSpace(nonOutput))
                    {
                        return nonOutput;
                    }
                }
                else
                {
                    var preferredOutput = keywordMatches.FirstOrDefault(name => name.Contains("output", StringComparison.OrdinalIgnoreCase));
                    if (!string.IsNullOrWhiteSpace(preferredOutput))
                    {
                        return preferredOutput;
                    }

                    var nonInput = keywordMatches.FirstOrDefault(name => !name.Contains("input", StringComparison.OrdinalIgnoreCase));
                    if (!string.IsNullOrWhiteSpace(nonInput))
                    {
                        return nonInput;
                    }
                }

                return keywordMatches.First();
            }

            if (!string.IsNullOrWhiteSpace(partyLedger) && amount > 0)
            {
                bool hasPartyLedger = existingEntries.Any(entry =>
                    !string.IsNullOrWhiteSpace(entry.LedgerName)
                    && string.Equals(entry.LedgerName.Trim(), partyLedger.Trim(), StringComparison.OrdinalIgnoreCase));

                if (!hasPartyLedger)
                {
                    var partyAmount = GetPartyLedgerSignedAmount(voucherType, amount);
                    output.Add(new VoucherLedgerEntry
                    {
                        LedgerName = partyLedger.Trim(),
                        Amount = partyAmount,
                        IsDebit = partyAmount < 0
                    });
                }
            }

            bool HasExistingTaxLedger(string taxKeyword, string? configuredLedgerName)
            {
                var configured = string.IsNullOrWhiteSpace(configuredLedgerName) ? null : configuredLedgerName.Trim();

                bool MatchesTaxLedger(VoucherLedgerEntry? entry)
                {
                    var ledgerName = entry?.LedgerName?.Trim();
                    if (string.IsNullOrWhiteSpace(ledgerName))
                    {
                        return false;
                    }

                    if (!string.IsNullOrWhiteSpace(configured)
                        && string.Equals(ledgerName, configured, StringComparison.OrdinalIgnoreCase))
                    {
                        return true;
                    }

                    return ledgerName.Contains(taxKeyword, StringComparison.OrdinalIgnoreCase);
                }

                return existingEntries.Any(MatchesTaxLedger) || output.Any(MatchesTaxLedger);
            }

            void AddTaxLedger(decimal taxAmount, string? configuredLedgerName, string taxKeyword, string defaultSalesLedger, string defaultPurchaseLedger)
            {
                if (taxAmount <= 0)
                {
                    return;
                }

                if (HasExistingTaxLedger(taxKeyword, configuredLedgerName))
                {
                    return;
                }

                string ledgerName = ResolveTaxLedgerName(configuredLedgerName, taxKeyword, defaultSalesLedger, defaultPurchaseLedger);
                decimal signedAmount = isPurchaseLike ? -Math.Abs(taxAmount) : Math.Abs(taxAmount);
                output.Add(new VoucherLedgerEntry
                {
                    LedgerName = ledgerName,
                    Amount = signedAmount,
                    IsDebit = signedAmount < 0
                });
            }

            AddTaxLedger(cgstAmount, GetTokenString(voucherToken, "cgst_ledger", "cgst_ledger_name"), "cgst", "Output CGST", "Input CGST");
            AddTaxLedger(sgstAmount, GetTokenString(voucherToken, "sgst_ledger", "sgst_ledger_name"), "sgst", "Output SGST", "Input SGST");
            AddTaxLedger(igstAmount, GetTokenString(voucherToken, "igst_ledger", "igst_ledger_name"), "igst", "Output IGST", "Input IGST");
            AddTaxLedger(cessAmount, GetTokenString(voucherToken, "cess_ledger", "cess_ledger_name"), "cess", "Output CESS", "Input CESS");

            return output;
        }

        private static List<VoucherLedgerEntry> BuildAccountingOnlyFallbackLedgers(
            string voucherType,
            string partyLedger,
            decimal amount,
            List<VoucherInventoryEntry> inventoryEntries,
            List<VoucherLedgerEntry> existingEntries,
            string? preferredBusinessLedger,
            IEnumerable<string>? knownLedgerNames)
        {
            var ledgerMap = new Dictionary<string, decimal>(StringComparer.OrdinalIgnoreCase);

            void AddOrAccumulate(string ledgerName, decimal signedAmount)
            {
                if (string.IsNullOrWhiteSpace(ledgerName) || signedAmount == 0m)
                {
                    return;
                }

                var key = ledgerName.Trim();
                ledgerMap[key] = ledgerMap.TryGetValue(key, out var current)
                    ? current + signedAmount
                    : signedAmount;
            }

            foreach (var entry in existingEntries ?? new List<VoucherLedgerEntry>())
            {
                if (entry == null || string.IsNullOrWhiteSpace(entry.LedgerName) || entry.Amount == 0m)
                {
                    continue;
                }

                AddOrAccumulate(entry.LedgerName, entry.Amount);
            }

            bool isSalesLike = voucherType.Contains("sale", StringComparison.OrdinalIgnoreCase);
            bool isPurchaseLike = voucherType.Contains("purchase", StringComparison.OrdinalIgnoreCase);
            var safePartyLedger = string.IsNullOrWhiteSpace(partyLedger) ? string.Empty : partyLedger.Trim();

            if (!string.IsNullOrWhiteSpace(safePartyLedger) && amount > 0)
            {
                if (!ledgerMap.ContainsKey(safePartyLedger))
                {
                    AddOrAccumulate(safePartyLedger, GetPartyLedgerSignedAmount(voucherType, amount));
                }
            }

            string? businessLedger = preferredBusinessLedger;
            if (string.IsNullOrWhiteSpace(businessLedger))
            {
                businessLedger = ledgerMap.Keys.FirstOrDefault(name =>
                    !IsTaxLikeLedgerName(name)
                    && (string.IsNullOrWhiteSpace(safePartyLedger)
                        || !string.Equals(name, safePartyLedger, StringComparison.OrdinalIgnoreCase)));
            }

            if (string.IsNullOrWhiteSpace(businessLedger))
            {
                businessLedger = ResolveFallbackBusinessLedgerName(
                    knownLedgerNames,
                    isSalesLike,
                    isPurchaseLike,
                    safePartyLedger);
            }

            if (string.IsNullOrWhiteSpace(businessLedger))
            {
                businessLedger = isSalesLike ? "SALE" : isPurchaseLike ? "PURCHASE" : "Suspense A/c";
            }

            businessLedger = businessLedger.Trim();

            var inventoryBaseTotal = inventoryEntries
                .Where(item => item != null && item.Amount > 0)
                .Sum(item => Math.Abs(item.Amount));

            bool hasBusinessLedger = ledgerMap.Keys.Any(name =>
                !IsTaxLikeLedgerName(name)
                && !string.Equals(name, safePartyLedger, StringComparison.OrdinalIgnoreCase));

            if (!hasBusinessLedger && inventoryBaseTotal > 0)
            {
                var businessSignedAmount = isPurchaseLike ? -Math.Abs(inventoryBaseTotal) : Math.Abs(inventoryBaseTotal);
                AddOrAccumulate(businessLedger, businessSignedAmount);
            }

            var net = ledgerMap.Values.Sum();
            if (Math.Abs(net) >= 0.01m)
            {
                AddOrAccumulate(businessLedger, -net);
            }

            return ledgerMap
                .Where(pair => Math.Abs(pair.Value) >= 0.01m)
                .Select(pair => new VoucherLedgerEntry
                {
                    LedgerName = pair.Key,
                    Amount = Math.Round(pair.Value, 2, MidpointRounding.AwayFromZero),
                    IsDebit = pair.Value < 0
                })
                .ToList();
        }
        private static decimal GetPartyLedgerSignedAmount(string voucherType, decimal amount)
        {
            var safeAmount = Math.Abs(amount);
            bool isSalesLike = voucherType.Contains("sale", StringComparison.OrdinalIgnoreCase);
            bool isPaymentLike = voucherType.Contains("payment", StringComparison.OrdinalIgnoreCase);
            return (isSalesLike || isPaymentLike) ? -safeAmount : safeAmount;
        }

        private static string BuildPendingPushContext(
            string transactionId,
            string voucherType,
            string partyLedger,
            DateTime voucherDate,
            decimal amount,
            List<VoucherInventoryEntry> inventoryEntries,
            List<VoucherLedgerEntry> ledgerEntries,
            decimal cgstAmount,
            decimal sgstAmount,
            decimal igstAmount,
            decimal cessAmount)
        {
            var itemSummary = string.Join(", ",
                inventoryEntries
                    .Where(item => item != null && !string.IsNullOrWhiteSpace(item.StockItemName))
                    .Take(3)
                    .Select(item => $"{item.StockItemName} x{item.Quantity:0.###} @ {item.Rate:0.##} (GST {(item.TaxRate ?? 0m):0.##}%)"));

            if (inventoryEntries.Count > 3)
            {
                itemSummary = string.IsNullOrWhiteSpace(itemSummary)
                    ? $"+{inventoryEntries.Count - 3} more"
                    : itemSummary + $", +{inventoryEntries.Count - 3} more";
            }

            var ledgerSummary = string.Join(", ",
                ledgerEntries
                    .Where(entry => entry != null && !string.IsNullOrWhiteSpace(entry.LedgerName))
                    .Take(4)
                    .Select(entry => $"{entry.LedgerName}:{entry.Amount:0.##}"));

            if (ledgerEntries.Count > 4)
            {
                ledgerSummary = string.IsNullOrWhiteSpace(ledgerSummary)
                    ? $"+{ledgerEntries.Count - 4} more"
                    : ledgerSummary + $", +{ledgerEntries.Count - 4} more";
            }

            return $"id={transactionId}, type={voucherType}, party={partyLedger}, date={voucherDate:dd-MMM-yyyy}, amount={amount:0.##}, cgst={cgstAmount:0.##}, sgst={sgstAmount:0.##}, igst={igstAmount:0.##}, cess={cessAmount:0.##}, items={inventoryEntries.Count}[{itemSummary}], ledgers={ledgerEntries.Count}[{ledgerSummary}]";
        }

        private static string? ResolvePreferredBusinessLedgerFromGroups(IEnumerable<Ledger>? knownLedgers, bool isSalesLike)
        {
            if (knownLedgers == null)
            {
                return null;
            }

            var preferredName = isSalesLike ? "Sales" : "Purchase";
            var preferredGroup = isSalesLike ? "sales account" : "purchase account";
            var preferredKeyword = isSalesLike ? "sale" : "purch";

            var candidates = knownLedgers
                .Where(ledger => ledger != null && !string.IsNullOrWhiteSpace(ledger.Name))
                .Select(ledger => new
                {
                    Name = ledger.Name.Trim(),
                    Parent = (ledger.ParentGroup ?? ledger.LedgerGroup ?? string.Empty).Trim()
                })
                .Where(ledger => !string.IsNullOrWhiteSpace(ledger.Name))
                .Where(ledger => !IsPartyLikeLedgerGroup(ledger.Parent))
                .ToList();

            if (candidates.Count == 0)
            {
                return null;
            }

            var exact = candidates
                .Select(candidate => candidate.Name)
                .FirstOrDefault(name => string.Equals(name, preferredName, StringComparison.OrdinalIgnoreCase));
            if (!string.IsNullOrWhiteSpace(exact))
            {
                return exact;
            }

            var byParent = candidates
                .Where(candidate => candidate.Parent.Contains(preferredGroup, StringComparison.OrdinalIgnoreCase))
                .Select(candidate => candidate.Name)
                .OrderBy(name => name.Length)
                .FirstOrDefault();
            if (!string.IsNullOrWhiteSpace(byParent))
            {
                return byParent;
            }

            return candidates
                .Where(candidate => candidate.Name.Contains(preferredKeyword, StringComparison.OrdinalIgnoreCase))
                .Where(candidate => !IsLikelyPartyLedgerName(candidate.Name))
                .Select(candidate => candidate.Name)
                .OrderBy(name => name.Length)
                .FirstOrDefault();
        }

        private static string? ResolveFallbackBusinessLedgerName(
            IEnumerable<string>? ledgerNames,
            bool isSalesLike,
            bool isPurchaseLike,
            string? partyLedger)
        {
            if (ledgerNames == null)
            {
                return null;
            }

            var names = ledgerNames
                .Where(name => !string.IsNullOrWhiteSpace(name))
                .Select(name => name.Trim())
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .Where(name => string.IsNullOrWhiteSpace(partyLedger)
                    || !string.Equals(name, partyLedger, StringComparison.OrdinalIgnoreCase))
                .ToList();

            if (names.Count == 0)
            {
                return null;
            }

            if (isSalesLike)
            {
                var salesCandidate = names
                    .Where(name => name.Contains("sale", StringComparison.OrdinalIgnoreCase)
                        || name.Contains("revenue", StringComparison.OrdinalIgnoreCase)
                        || name.Contains("income", StringComparison.OrdinalIgnoreCase))
                    .FirstOrDefault(name => !IsTaxLikeLedgerName(name));
                if (!string.IsNullOrWhiteSpace(salesCandidate))
                {
                    return salesCandidate;
                }
            }

            if (isPurchaseLike)
            {
                var purchaseCandidate = names
                    .Where(name => name.Contains("purch", StringComparison.OrdinalIgnoreCase)
                        || name.Contains("expense", StringComparison.OrdinalIgnoreCase)
                        || name.Contains("consum", StringComparison.OrdinalIgnoreCase))
                    .FirstOrDefault(name => !IsTaxLikeLedgerName(name));
                if (!string.IsNullOrWhiteSpace(purchaseCandidate))
                {
                    return purchaseCandidate;
                }
            }

            var cashOrBank = names.FirstOrDefault(name =>
                name.Equals("Cash", StringComparison.OrdinalIgnoreCase)
                || name.Contains("cash", StringComparison.OrdinalIgnoreCase)
                || name.Contains("bank", StringComparison.OrdinalIgnoreCase));
            if (!string.IsNullOrWhiteSpace(cashOrBank))
            {
                return cashOrBank;
            }

            return names.FirstOrDefault(name => !IsTaxLikeLedgerName(name)) ?? names.FirstOrDefault();
        }

        private static bool IsTaxLikeLedgerName(string? ledgerName)
        {
            if (string.IsNullOrWhiteSpace(ledgerName))
            {
                return false;
            }

            var value = ledgerName.Trim();
            return value.Contains("gst", StringComparison.OrdinalIgnoreCase)
                || value.Contains("cgst", StringComparison.OrdinalIgnoreCase)
                || value.Contains("sgst", StringComparison.OrdinalIgnoreCase)
                || value.Contains("igst", StringComparison.OrdinalIgnoreCase)
                || value.Contains("cess", StringComparison.OrdinalIgnoreCase)
                || value.Contains("tax", StringComparison.OrdinalIgnoreCase)
                || value.Contains("round", StringComparison.OrdinalIgnoreCase)
                || value.Contains("duty", StringComparison.OrdinalIgnoreCase);
        }
        private static bool IsPartyLikeLedgerGroup(string? parentGroup)
        {
            if (string.IsNullOrWhiteSpace(parentGroup))
            {
                return false;
            }

            var value = parentGroup.Trim();
            return value.Contains("sundry debt", StringComparison.OrdinalIgnoreCase)
                || value.Contains("sundry cred", StringComparison.OrdinalIgnoreCase)
                || value.Contains("bank", StringComparison.OrdinalIgnoreCase)
                || value.Contains("cash", StringComparison.OrdinalIgnoreCase)
                || value.Contains("loan", StringComparison.OrdinalIgnoreCase)
                || value.Contains("duties", StringComparison.OrdinalIgnoreCase)
                || value.Contains("tax", StringComparison.OrdinalIgnoreCase);
        }

        private static bool IsLikelyPartyLedgerName(string ledgerName)
        {
            if (string.IsNullOrWhiteSpace(ledgerName))
            {
                return false;
            }

            var value = ledgerName.Trim();
            return value.Contains("agency", StringComparison.OrdinalIgnoreCase)
                || value.Contains("agencies", StringComparison.OrdinalIgnoreCase)
                || value.Contains("industr", StringComparison.OrdinalIgnoreCase)
                || value.Contains("enterprise", StringComparison.OrdinalIgnoreCase)
                || value.Contains("trader", StringComparison.OrdinalIgnoreCase)
                || value.Contains("trading", StringComparison.OrdinalIgnoreCase)
                || value.Contains("supplier", StringComparison.OrdinalIgnoreCase)
                || value.Contains("customer", StringComparison.OrdinalIgnoreCase)
                || value.Contains("client", StringComparison.OrdinalIgnoreCase)
                || value.Contains("distributor", StringComparison.OrdinalIgnoreCase)
                || value.Contains("wholesale", StringComparison.OrdinalIgnoreCase)
                || value.Contains("retail", StringComparison.OrdinalIgnoreCase);
        }
        private static int GetRetryAttempt(PendingTransaction transaction)
        {
            if (transaction.RetryCount > 0)
            {
                return transaction.RetryCount;
            }

            if (string.IsNullOrWhiteSpace(transaction.ErrorMessage))
            {
                return 0;
            }

            var match = RetryTagRegex.Match(transaction.ErrorMessage);
            return match.Success && int.TryParse(match.Groups[1].Value, out var parsedAttempt)
                ? parsedAttempt
                : 0;
        }

        private static string AppendRetryMetadata(string? message, int attempt)
        {
            var clean = string.IsNullOrWhiteSpace(message)
                ? "Unknown error"
                : RetryTagRegex.Replace(message, string.Empty).Trim();

            return $"{clean} [retry {attempt}/{MaxPendingPushRetries}]";
        }

        /// <summary>
        /// Normalize voucher type from database format to valid Tally voucher type.
        /// Database may store table names like "VOUCHERS" or generic types.
        /// Tally requires exact type names: Sales, Purchase, Receipt, Payment, Journal, etc.
        /// </summary>
        private string NormalizeTallyVoucherType(string rawType, dynamic voucherData)
        {
            if (string.IsNullOrEmpty(rawType)) return "Receipt";

            // 1. First try to get the actual voucher type from the voucher data itself
            string? typeFromData = null;
            try
            {
                typeFromData = voucherData?.voucher_type_name?.ToString() ??
                               voucherData?.voucherTypeName?.ToString() ??
                               voucherData?.voucher_type?.ToString() ??
                               voucherData?.voucherType?.ToString() ??
                               voucherData?.type?.ToString();
            }
            catch { /* dynamic access may fail, ignore */ }

            // If we found a type in voucher data and it's a valid Tally type, use it
            if (!string.IsNullOrEmpty(typeFromData))
            {
                var normalizedFromData = MapToTallyType(typeFromData);
